$(function(){var tablas=$('.presupuesto-tabla').DataTable({paging:false,info:false,searching:true,ordering:true,autoWidth:false,language:{search:'Buscar en esta actividad:',zeroRecords:'No se encontraron cuentas'}});$('#toggle-detalle').on('click',function(){var abierto=$('body').toggleClass('mostrar-detalle').hasClass('mostrar-detalle');$(this).text(abierto?'Ver resumen':'Ver detalle mensual');tablas.columns.adjust();});
const dialog=document.getElementById('budget-orders-dialog'),summary=dialog.querySelector('[data-budget-orders-summary]'),content=dialog.querySelector('[data-budget-orders-content]'),money=new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}),canOpenOrders=<?= $puedeVerListadoOrdenes ? 'true' : 'false' ?>;
const addCell=(row,text)=>{const cell=document.createElement('td');cell.textContent=text;row.appendChild(cell);};
document.addEventListener('click',async event=>{const button=event.target.closest('.budget-commitment-trigger');if(button){dialog.showModal();summary.textContent='Cargando las órdenes relacionadas…';content.replaceChildren();const query=new URLSearchParams({r:'presupuesto_ordenes',actividad:button.dataset.activity,cuenta:button.dataset.account,inversion:button.dataset.investment,periodo:button.dataset.period,unidad:button.dataset.unit,tipo:button.dataset.budgetType});try{const response=await fetch('<?= e(APP_URL) ?>?'+query.toString(),{headers:{Accept:'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.error||'No se pudo consultar el detalle.');const label=result.periodo==='total'?'compromiso anual':result.periodo;summary.textContent='Compromiso '+label+' ('+result.anio+'): S/ '+money.format(result.total)+'. Vinculado a órdenes: S/ '+money.format(result.vinculado)+'. Sin orden de logística identificable: S/ '+money.format(result.sin_orden)+'.';if(!result.ordenes.length){const empty=document.createElement('p');empty.className='budget-orders-empty';empty.textContent='No se encontraron órdenes de compra o servicio vinculadas a este compromiso.';content.appendChild(empty);return;}const table=document.createElement('table'),thead=document.createElement('thead'),head=document.createElement('tr'),body=document.createElement('tbody');['Orden','Expediente','Fecha','Estado','Monto de orden','Compromiso asociado'].forEach(title=>{const th=document.createElement('th');th.textContent=title;head.appendChild(th);});thead.appendChild(head);result.ordenes.forEach(order=>{const row=document.createElement('tr'),currency=order.moneda==='01'?'S/ ':order.moneda?order.moneda+' ':'— ';addCell(row,(order.tipo==='Compra'?'OC ':'OS ')+order.numero);addCell(row,order.expediente||'—');addCell(row,order.fecha||'—');addCell(row,order.estado==='A'?'Anulada':order.estado||'Sin estado');addCell(row,order.total===null?'No disponible':currency+money.format(order.total));addCell(row,order.compromiso===null?'Varios compromisos, sin distribución por orden': 'S/ '+money.format(order.compromiso));body.appendChild(row);});table.append(thead,body);table.className='budget-orders-table';content.appendChild(table);if(canOpenOrders){const link=document.createElement('a'),target=new URL('<?= e(url('ordenes')) ?>',window.location.href);result.ordenes.forEach(order=>target.searchParams.append('ordenes[]',(order.tipo==='Compra'?'orden_compra':'orden_servicio')+'|'+order.numero));link.href=target.toString();link.className='orders-open-budget';link.innerHTML='<i class="bi bi-box-arrow-up-right" aria-hidden="true"></i> Ver estas órdenes en el listado';content.appendChild(link);}}catch(error){summary.textContent=error.message;}}});
dialog.addEventListener('click',event=>{if(event.target===dialog||event.target.closest('[data-close-budget-orders]'))dialog.close();});
});
</script>
